let rayvnConfig = flow.get('rayvnConfig') || {};

if (msg.topic === 'rayvn_api_key') {
    rayvnConfig.apiKey = msg.payload;
} else if (msg.topic === 'log_name') {
    rayvnConfig.logName = msg.payload;
}

flow.set('rayvnConfig', rayvnConfig);

return null;

let wasosConfig = flow.get('wasosConfig') || {};

if (msg.topic === 'wasos_username') {
    wasosConfig.username = msg.payload;
} else if (msg.topic === 'wasos_password') {
    // IKKE lagre passordet - sett det bare på meldingen
    msg.password = msg.payload;
    return msg;  // Send direkte til neste node
} else if (msg.topic === 'chatroom_name') {
    wasosConfig.chatroom = msg.payload;
}

flow.set('wasosConfig', wasosConfig);

return null;

let rayvnConfig = flow.get('rayvnConfig') || {};

node.warn('Retrieved Rayvn config: ' + JSON.stringify({ ...rayvnConfig, apiKey: '***' }));

if (!rayvnConfig.apiKey || !rayvnConfig.logName) {
    node.warn('Missing required Rayvn fields');
    msg.payload = 'Vennligst fyll ut alle påkrevde Rayvn-felt.';
    msg.topic = 'Error';
    msg.color = '#F44336';
    return msg;
}

// Prepare to fetch logs from Rayvn
msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey
};
msg.url = "https://api.rayvn.global/logs";
msg.rayvnConfig = rayvnConfig; // Pass config along

return msg;

let wasosConfig = flow.get('wasosConfig') || {};
let password = flow.get('temp_password');  // Hent midlertidig passord

node.warn('Retrieved config (no password): ' + JSON.stringify(wasosConfig));

if (!wasosConfig.username || !password || !wasosConfig.chatroom) {
    node.warn('Missing required WaSOS fields');
    msg.payload = 'Vennligst fyll ut alle påkrevde WaSOS-felt.';
    msg.topic = 'Error';
    msg.color = '#F44336';
    return [msg, null];
}

const wasosBaseUrl = "https://dev.wasos.no";

msg.username = wasosConfig.username;
msg.password = password;
msg.url = wasosBaseUrl;

// Slett midlertidig passord etter bruk
flow.set('temp_password', null);

const chatroomUrl = `${wasosBaseUrl}/api/chat/messages/${wasosConfig.chatroom}`;
flow.set('wasosChatroomUrl', chatroomUrl);
flow.set('wasosChatroomName', wasosConfig.chatroom);

msg.payload = `WaSOS-konfigurasjon lagret! Chatrom: ${wasosConfig.chatroom}`;
msg.topic = 'Success';
msg.color = '#4CAF50';

return [null, msg];

let chatroom = flow.get('wasosChatroomName');

if (msg.payload && msg.payload.nonce) {
    // Login vellykket
    msg.payload = `WaSOS-tilkobling vellykket! Chatrom: ${chatroom}`;
    msg.color = '#4CAF50';
} else {
    // Login feilet
    msg.payload = 'WaSOS-tilkobling feilet. Sjekk brukernavn og passord.';
    msg.color = '#F44336';
}

return msg;

const body = msg.payload || {};
const messages = Array.isArray(body.messages) ? body.messages : [];

// Nothing to do
if (messages.length === 0) {
    msg.payload = [];
    return msg;
}

// Sort oldest -> newest using numeric timestamps (avoids TS complaining)
messages.sort((a, b) => {
    const ta = new Date(a.createdAt).getTime();
    const tb = new Date(b.createdAt).getTime();
    return ta - tb;
});

// Track last forwarded per room
const roomId = String(messages[0].roomId || "default");
const key = `lastForwardedId_${roomId}`;

const lastId = flow.get(key);

// First run: set cursor but don't forward history
if (!lastId) {
    const latest = messages[messages.length - 1];
    flow.set(key, latest.id);
    msg.payload = [];
    return msg;
}

// Collect messages after lastId
const newMessages = [];
let seen = false;

for (const m of messages) {
    if (seen) newMessages.push(m);
    if (m.id === lastId) seen = true;
}

// If lastId not found, forward only latest (prevents spam)
if (!seen) {
    const latest = messages[messages.length - 1];
    flow.set(key, latest.id);
    msg.payload = [latest];
    return msg;
}

// Update cursor to newest forwarded
if (newMessages.length > 0) {
    flow.set(key, newMessages[newMessages.length - 1].id);
}

msg.payload = newMessages;
return msg;

const rayvnConfig = flow.get('rayvnConfig') || {};
const logId = flow.get('rayvnLogId');

// Validation
if (!rayvnConfig.apiKey || !logId) {
    node.error('Rayvn not configured. Please submit Rayvn configuration first.');
    return null;
}

const m = msg.payload; // one chat message after Split

msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey,
    "Content-Type": "application/json",
    "Accept": "application/json"
};

msg.url = `https://api.rayvn.global/logs/${logId}/entry`;

// Put the chat content into Rayvn entry text
msg.payload = {
    text: `[${m.username}] ${m.content}`,
    keyEvent: false,
    releasedInfo: false,
    labels: [
        { id: "8d8f4cd8-c57c-4ddd-861c-f515237c75d1" }
    ]
};

return msg;

let wasosApiKey = flow.get('wasos_apikey');
let chatroomUrl = flow.get('wasosChatroomUrl');

if (!wasosApiKey || !chatroomUrl) {
    node.error('WaSOS not configured. Please submit WaSOS configuration first.');
    return null;
}

msg.headers = {
    'x-api-key': wasosApiKey
};
msg.url = chatroomUrl + '?limit=50';

return msg;

const rayvnConfig = msg.rayvnConfig;
const logName = rayvnConfig.logName.trim();

try {
    const logs = JSON.parse(msg.payload);

    // Find matching logs (case-insensitive exact match)
    const matches = logs.filter(log =>
        log.name.toLowerCase() === logName.toLowerCase()
    );

    if (matches.length === 0) {
        msg.payload = `Logg '${logName}' ble ikke funnet i Rayvn.`;
        msg.topic = 'Error';
        msg.color = '#F44336';
        return msg;
    }

    if (matches.length > 1) {
        // Multiple logs with same name - need user to choose
        msg.payload = `Fant ${matches.length} logger med navn '${logName}'. Vennligst kontakt administrator.`;
        msg.topic = 'Error';
        msg.color = '#F44336';
        return msg;
    }

    // Success! Store the log ID
    const logId = matches[0].id;
    flow.set('rayvnLogId', logId);

    msg.payload = `Rayvn-konfigurasjon lagret! Logg: ${logName} (ID: ${logId})`;
    msg.topic = 'Success';
    msg.color = '#4CAF50';

    return msg;

} catch (e) {
    msg.payload = 'Feil ved henting av Rayvn-logger: ' + e.message;
    msg.topic = 'Error';
    msg.color = '#F44336';
    return msg;
}

let wasosApiKey = flow.get('wasos_apikey');
let rayvnConfig = flow.get('rayvnConfig') || {};
let rayvnLogId = flow.get('rayvnLogId');

if (!wasosApiKey || !rayvnConfig.apiKey || !rayvnLogId) {
    node.warn('Systemene er ikke fullstendig konfigurert. Vennligst fullfør både WaSOS- og Rayvn-konfigurasjon.');
    return null;
}

return msg;

let wasosApiKey = flow.get('wasos_apikey');
let rayvnConfig = flow.get('rayvnConfig') || {};
let rayvnLogId = flow.get('rayvnLogId');

if (!wasosApiKey || !rayvnConfig.apiKey || !rayvnLogId) {
    node.warn('Systemene er ikke fullstendig konfigurert for Rayvn → WaSOS.');
    return null;
}

return msg;

const rayvnConfig = flow.get('rayvnConfig') || {};
const logId = flow.get('rayvnLogId');

if (!rayvnConfig.apiKey || !logId) {
    node.error('Rayvn not configured.');
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey
};

msg.url = `https://api.rayvn.global/logs/${logId}/entries`;

return msg;
